sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading ) {
        return;
    }

	if (newValue == '') {
        return;
    }

    var ga = new GlideAjax('ControlAssigmentsUtils');
    ga.addParam('sysparm_name', 'controlRegistration'); // Nome do método no Script Include
    ga.addParam('sysparm_user_id', g_user.userID);

    ga.getXML(callBackFunction);

    function callBackFunction(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
        if (answer === 'true') {
            g_form.addErrorMessage("You are already registered in a Base.");
            g_form.clearValue("base");
        } 
    }



    //Type appropriate comment here, and begin script below

}
